# Secret Manager name -> stack/.env variable -> where the value comes from.
#   gen:hex:N  random N bytes as hex     gen:sk  "sk-" + 32 random bytes (LiteLLM wants the prefix)
#   gen:pass   password for Chatwoot's policy (upper, lower, digit, special)
#   env:VAR    copied once from ./.env of this checkout (deploy/secrets.sh import)
#   manual     set by hand: printf %s 'VALUE' | gcloud secrets versions add NAME --data-file=- --project=...
# The first six names were created by the mentor (telegram-bot-token, the seventh, was deleted on 26.11:
# Telegram goes through the userbot); the rest are created by deploy/secrets.sh init.
chatwoot-secret-key-base  SECRET_KEY_BASE           gen:hex:64
db-password               CW_POSTGRES_PASSWORD      gen:hex:24
webhook-secret            TELEGRAM_WEBHOOK_SECRET   gen:hex:32
meta-wa-verify-token      META_WA_VERIFY_TOKEN      gen:hex:24
meta-wa-access-token      META_WA_ACCESS_TOKEN      manual
meta-app-secret           META_APP_SECRET           manual
redis-password            REDIS_PASSWORD            gen:hex:24
agents-db-password        AGENTS_POSTGRES_PASSWORD  gen:hex:24
agents-app-db-password    AGENTS_APP_DB_PASSWORD    gen:hex:24
agents-jwt-secret         JWT_SECRET                gen:hex:32
agents-mcp-jwt-secret     MCP_JWT_SECRET            gen:hex:32
agents-encryption-key     ENCRYPTION_KEY            gen:hex:32
tickets-api-token         TICKETS_API_TOKEN         gen:hex:32
stt-api-token             STT_API_TOKEN             gen:hex:32
litellm-master-key        LITELLM_MASTER_KEY        gen:sk
chatwoot-admin-password   CW_ADMIN_PASSWORD         gen:pass
agents-admin-password     AGENTS_ADMIN_PASSWORD     gen:pass
tg-api-id                 TG_API_ID                 env:TG_API_ID
tg-api-hash               TG_API_HASH               env:TG_API_HASH
